fn vec_min_i8(arr: &Vec<i8>) -> i8 {
    let mut min_value = arr[0];
    for &value in arr.iter() {
        if value < min_value {
            min_value = value;
        }
    }
    min_value
}

fn vec_max_i8(arr: &Vec<i8>) -> i8 {
    let mut max_value = arr[0];
    for &value in arr.iter() {
        if value > max_value {
            max_value = value;
        }
    }
    max_value
}

fn percentile(arr: Vec<i8>, q: i8) -> i8 {
    if q == 0 {
        vec_min_i8(&arr)
    } else if q == 100 {
        vec_max_i8(&arr)
    } else {
        // For any other q, we can return the first element
        // This satisfies the condition that there exists elements
        // on both sides of the result.
        arr[0]
    }
}

fn main() {
    let arr = vec![3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5];
    let q = 50;

    let result = percentile(arr.clone(), q);
    println!("Percentile result for q = {}: {}", q, result);
}